/**
 * Tactile Sensor Simulation
 * Models DIGIT, GelSight, and ReSkin sensor responses
 */

// Generate synthetic tactile sensor reading
export function generateSensorReading(sensorType, contactParams, material) {
  switch (sensorType) {
    case 'DIGIT':
      return generateDIGITReading(contactParams, material);
    case 'GelSight':
      return generateGelSightReading(contactParams, material);
    case 'ReSkin':
      return generateReSkinReading(contactParams, material);
    default:
      return generateDIGITReading(contactParams, material);
  }
}

// DIGIT: Gel-based optical sensor (image-based)
function generateDIGITReading(contactParams, material) {
  const { force, position, orientation, shear } = contactParams;

  // Simulate gel deformation image as feature vector
  const resolution = 32 * 32; // Simulated 32x32 image
  const reading = new Array(resolution);

  const materialProps = getMaterialProps(material);

  for (let i = 0; i < resolution; i++) {
    const x = (i % 32) / 32;
    const y = Math.floor(i / 32) / 32;

    // Gel deformation based on distance from contact point
    const dx = x - position[0];
    const dy = y - position[1];
    const dist = Math.sqrt(dx * dx + dy * dy);

    // Gaussian deformation profile
    const deformation = force * materialProps.compliance *
      Math.exp(-dist * dist / (0.1 + materialProps.stiffness));

    // Add optical pattern based on material texture
    const texture = Math.sin(x * 20 * materialProps.roughness) *
                   Math.cos(y * 20 * materialProps.roughness);

    reading[i] = deformation + texture * 0.1 + (Math.random() - 0.5) * 0.02;
  }

  return reading;
}

// GelSight: Marker tracking optical sensor
function generateGelSightReading(contactParams, material) {
  const { force, position, shear } = contactParams;

  // Simulate marker displacements
  const numMarkers = 256; // 16x16 marker grid
  const reading = new Array(numMarkers * 2); // x, y displacement for each marker

  const materialProps = getMaterialProps(material);

  for (let i = 0; i < numMarkers; i++) {
    const mx = (i % 16) / 16;
    const my = Math.floor(i / 16) / 16;

    const dx = mx - position[0];
    const dy = my - position[1];
    const dist = Math.sqrt(dx * dx + dy * dy);

    // Marker displacement proportional to force and material compliance
    const displacementMag = force * materialProps.compliance *
      Math.exp(-dist * dist / 0.05);

    const angle = Math.atan2(dy, dx);
    reading[i * 2] = displacementMag * Math.cos(angle) + shear[0] * 0.5 +
                     (Math.random() - 0.5) * 0.01;
    reading[i * 2 + 1] = displacementMag * Math.sin(angle) + shear[1] * 0.5 +
                         (Math.random() - 0.5) * 0.01;
  }

  return reading;
}

// ReSkin: Magnetic sensor array
function generateReSkinReading(contactParams, material) {
  const { force, position, shear } = contactParams;

  // Simulate magnetic field readings from 5 magnetometers
  const numSensors = 5;
  const reading = new Array(numSensors * 3); // Bx, By, Bz for each sensor

  const materialProps = getMaterialProps(material);

  const sensorPositions = [
    [0.5, 0.5],  // Center
    [0.3, 0.3],  // Top-left
    [0.7, 0.3],  // Top-right
    [0.3, 0.7],  // Bottom-left
    [0.7, 0.7]   // Bottom-right
  ];

  sensorPositions.forEach((spos, i) => {
    const dx = spos[0] - position[0];
    const dy = spos[1] - position[1];
    const dist = Math.sqrt(dx * dx + dy * dy);

    // Magnetic field distortion due to deformation
    const fieldStrength = force * materialProps.compliance *
      Math.exp(-dist * dist / 0.08);

    // Bx, By, Bz components
    reading[i * 3] = fieldStrength * dx / (dist + 0.01) + shear[0] * 0.3 +
                     (Math.random() - 0.5) * 0.03;
    reading[i * 3 + 1] = fieldStrength * dy / (dist + 0.01) + shear[1] * 0.3 +
                         (Math.random() - 0.5) * 0.03;
    reading[i * 3 + 2] = fieldStrength + (Math.random() - 0.5) * 0.02;
  });

  return reading;
}

// Material properties
function getMaterialProps(material) {
  const materials = {
    rubber: { compliance: 0.8, stiffness: 0.3, roughness: 0.2, friction: 0.7 },
    metal: { compliance: 0.1, stiffness: 0.9, roughness: 0.05, friction: 0.3 },
    plastic: { compliance: 0.4, stiffness: 0.6, roughness: 0.3, friction: 0.4 },
    foam: { compliance: 1.0, stiffness: 0.1, roughness: 0.4, friction: 0.5 },
    wood: { compliance: 0.3, stiffness: 0.7, roughness: 0.6, friction: 0.6 }
  };

  return materials[material] || materials.plastic;
}

// Generate contact parameters for a given task
export function generateContactParams(task, time) {
  const tasks = {
    'peg-insertion': generatePegInsertionContact(time),
    'connector-insertion': generateConnectorInsertionContact(time),
    'surface-exploration': generateSurfaceExplorationContact(time),
    'texture-recognition': generateTextureRecognitionContact(time),
    'grasp-stability': generateGraspStabilityContact(time)
  };

  return tasks[task] || tasks['connector-insertion'];
}

function generatePegInsertionContact(time) {
  const phase = time % 5.0;

  return {
    force: Math.min(2.0, phase * 0.4 + 0.5 + Math.sin(time * 2) * 0.1),
    position: [
      0.5 + Math.sin(time * 0.5) * 0.1,
      0.5 + Math.cos(time * 0.5) * 0.1
    ],
    orientation: [0, 0, -1],
    shear: [
      Math.sin(time * 1.5) * 0.2,
      Math.cos(time * 1.5) * 0.2
    ]
  };
}

function generateConnectorInsertionContact(time) {
  const phase = (time % 8.0) / 8.0;

  return {
    force: 1.5 + Math.sin(phase * Math.PI) * 0.5 + (Math.random() - 0.5) * 0.2,
    position: [
      0.5 + Math.sin(time * 0.3) * 0.15,
      0.4 + phase * 0.2
    ],
    orientation: [0, 0, -1],
    shear: [
      Math.cos(time * 2) * 0.15,
      Math.sin(time * 1.8) * 0.15
    ]
  };
}

function generateSurfaceExplorationContact(time) {
  return {
    force: 0.8 + Math.sin(time) * 0.3,
    position: [
      0.5 + Math.sin(time * 0.8) * 0.3,
      0.5 + Math.cos(time * 0.8) * 0.3
    ],
    orientation: [0, 0, -1],
    shear: [
      Math.cos(time * 1.2) * 0.25,
      Math.sin(time * 1.5) * 0.25
    ]
  };
}

function generateTextureRecognitionContact(time) {
  return {
    force: 1.2 + (Math.random() - 0.5) * 0.3,
    position: [
      0.3 + (time % 3.0) / 3.0 * 0.4,
      0.5 + Math.sin(time * 2) * 0.1
    ],
    orientation: [0, 0, -1],
    shear: [
      (Math.random() - 0.5) * 0.1,
      (Math.random() - 0.5) * 0.1
    ]
  };
}

function generateGraspStabilityContact(time) {
  const vibration = Math.sin(time * 10) * 0.05;

  return {
    force: 2.0 + vibration + (Math.random() - 0.5) * 0.1,
    position: [0.5, 0.5],
    orientation: [0, 0, -1],
    shear: [
      vibration * 2,
      Math.cos(time * 8) * 0.1
    ]
  };
}

// Domain randomization for sim2real
export function applyDomainRandomization(reading, strength = 0.3) {
  return reading.map(val => {
    const noise = (Math.random() - 0.5) * strength;
    const dropout = Math.random() < 0.05 ? 0 : 1; // 5% dropout
    return (val + noise) * dropout;
  });
}

// Sensor calibration error
export function applySensorBias(reading, sensorType) {
  const biases = {
    'DIGIT': 0.02,
    'GelSight': 0.015,
    'ReSkin': 0.03
  };

  const bias = biases[sensorType] || 0.02;

  return reading.map((val, i) => val + Math.sin(i * 0.1) * bias);
}

// Data augmentation for training
export function augmentTactileData(reading, augType) {
  switch (augType) {
    case 'noise':
      return reading.map(v => v + (Math.random() - 0.5) * 0.1);
    case 'scale':
      const scale = 0.8 + Math.random() * 0.4;
      return reading.map(v => v * scale);
    case 'shift':
      const shift = (Math.random() - 0.5) * 0.2;
      return reading.map(v => v + shift);
    case 'dropout':
      return reading.map(v => Math.random() < 0.1 ? 0 : v);
    default:
      return reading;
  }
}
