/**
 * Surface Reconstruction from Tactile Embeddings
 * Implements PointNet++-style decoder for geometry and force prediction
 */

import * as THREE from 'three';

// Decode tactile embedding to 3D surface points with forces
export class SurfaceDecoder {
  constructor(embeddingDim, numPoints = 256) {
    this.embeddingDim = embeddingDim;
    this.numPoints = numPoints;
    this.weights = this.initializeWeights();
  }

  initializeWeights() {
    // Simple MLP decoder: embedding -> [numPoints * (x,y,z,fx,fy,fz)]
    const outputDim = this.numPoints * 6; // 3 for position, 3 for force

    const dims = [this.embeddingDim, 256, 512, outputDim];
    const weights = [];

    for (let i = 0; i < dims.length - 1; i++) {
      const W = Array(dims[i + 1]).fill(0).map(() =>
        Array(dims[i]).fill(0).map(() => (Math.random() - 0.5) * 0.1)
      );
      const b = Array(dims[i + 1]).fill(0).map(() => (Math.random() - 0.5) * 0.05);
      weights.push({ W, b });
    }

    return weights;
  }

  decode(embedding) {
    let activation = embedding;

    for (let i = 0; i < this.weights.length; i++) {
      const { W, b } = this.weights[i];
      activation = this.linearLayer(activation, W, b);

      // ReLU activation (except last layer uses tanh)
      if (i < this.weights.length - 1) {
        activation = activation.map(x => Math.max(0, x));
      } else {
        activation = activation.map(x => Math.tanh(x));
      }
    }

    // Reshape to points: [[x,y,z,fx,fy,fz], ...]
    const points = [];
    for (let i = 0; i < this.numPoints; i++) {
      points.push(activation.slice(i * 6, (i + 1) * 6));
    }

    return points;
  }

  linearLayer(input, W, b) {
    return W.map((weights, i) => {
      const sum = weights.reduce((acc, w, j) => acc + w * input[j], 0);
      return sum + b[i];
    });
  }
}

// Compute Chamfer distance between two point clouds
export function chamferDistance(points1, points2) {
  const dist1to2 = points1.map(p1 => {
    const distances = points2.map(p2 =>
      Math.sqrt(
        (p1[0] - p2[0]) ** 2 +
        (p1[1] - p2[1]) ** 2 +
        (p1[2] - p2[2]) ** 2
      )
    );
    return Math.min(...distances);
  });

  const dist2to1 = points2.map(p2 => {
    const distances = points1.map(p1 =>
      Math.sqrt(
        (p1[0] - p2[0]) ** 2 +
        (p1[1] - p2[1]) ** 2 +
        (p1[2] - p2[2]) ** 2
      )
    );
    return Math.min(...distances);
  });

  const avgDist1 = dist1to2.reduce((a, b) => a + b, 0) / dist1to2.length;
  const avgDist2 = dist2to1.reduce((a, b) => a + b, 0) / dist2to1.length;

  return (avgDist1 + avgDist2) / 2;
}

// Generate mesh from point cloud with normals
export function generateMeshFromPoints(points, resolution = 32) {
  const geometry = new THREE.BufferGeometry();

  // Extract positions and forces
  const positions = [];
  const forces = [];
  const colors = [];

  points.forEach(point => {
    positions.push(point[0], point[1], point[2]);
    forces.push(point[3], point[4], point[5]);

    // Color by force magnitude
    const forceMag = Math.sqrt(point[3]**2 + point[4]**2 + point[5]**2);
    const hue = Math.max(0, Math.min(1, 1 - forceMag)) * 0.7; // Red=high, Blue=low
    const color = new THREE.Color().setHSL(hue, 0.8, 0.5);
    colors.push(color.r, color.g, color.b);
  });

  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

  // Compute vertex normals
  geometry.computeVertexNormals();

  return geometry;
}

// Compute surface normals from point cloud
export function estimateNormals(points, k = 10) {
  const normals = [];

  for (let i = 0; i < points.length; i++) {
    const p = points[i];

    // Find k nearest neighbors
    const neighbors = points
      .map((q, idx) => ({
        idx,
        dist: Math.sqrt((p[0]-q[0])**2 + (p[1]-q[1])**2 + (p[2]-q[2])**2)
      }))
      .sort((a, b) => a.dist - b.dist)
      .slice(1, k + 1)
      .map(n => points[n.idx]);

    // Compute covariance matrix
    const mean = [0, 0, 0];
    neighbors.forEach(n => {
      mean[0] += n[0];
      mean[1] += n[1];
      mean[2] += n[2];
    });
    mean[0] /= neighbors.length;
    mean[1] /= neighbors.length;
    mean[2] /= neighbors.length;

    // Simplified PCA: use cross product of first two centered neighbors
    if (neighbors.length >= 2) {
      const v1 = [
        neighbors[0][0] - mean[0],
        neighbors[0][1] - mean[1],
        neighbors[0][2] - mean[2]
      ];
      const v2 = [
        neighbors[1][0] - mean[0],
        neighbors[1][1] - mean[1],
        neighbors[1][2] - mean[2]
      ];

      const normal = [
        v1[1] * v2[2] - v1[2] * v2[1],
        v1[2] * v2[0] - v1[0] * v2[2],
        v1[0] * v2[1] - v1[1] * v2[0]
      ];

      const norm = Math.sqrt(normal[0]**2 + normal[1]**2 + normal[2]**2);
      normals.push(normal.map(x => x / (norm + 1e-8)));
    } else {
      normals.push([0, 0, 1]);
    }
  }

  return normals;
}

// Physics-based contact force prediction
export function predictContactForces(surfacePoints, material, normalForce = 1.0) {
  const forces = [];

  // Material properties
  const materials = {
    rubber: { stiffness: 0.5, friction: 0.7, damping: 0.3 },
    metal: { stiffness: 10.0, friction: 0.3, damping: 0.1 },
    plastic: { stiffness: 2.0, friction: 0.4, damping: 0.2 },
    foam: { stiffness: 0.1, friction: 0.5, damping: 0.5 },
    wood: { stiffness: 3.0, friction: 0.6, damping: 0.15 }
  };

  const props = materials[material] || materials.plastic;

  surfacePoints.forEach(point => {
    // Normal force based on penetration depth (z-component)
    const penetration = Math.max(0, -point[2]);
    const fn = props.stiffness * penetration * normalForce;

    // Tangential force (friction)
    const ft = props.friction * fn;

    // Add some noise for realism
    const noise = () => (Math.random() - 0.5) * 0.1;

    forces.push([
      noise() * ft,
      noise() * ft,
      fn + noise() * 0.1
    ]);
  });

  return forces;
}

// Marching cubes for implicit surface reconstruction
export function marchingCubesReconstruction(points, resolution = 32, isovalue = 0.5) {
  // Build occupancy grid from points
  const grid = createOccupancyGrid(points, resolution);

  // Extract isosurface (simplified)
  const vertices = [];
  const indices = [];

  for (let x = 0; x < resolution - 1; x++) {
    for (let y = 0; y < resolution - 1; y++) {
      for (let z = 0; z < resolution - 1; z++) {
        const cube = extractCube(grid, x, y, z, resolution);
        const cubeIndices = marchCube(cube, isovalue);

        cubeIndices.forEach(idx => {
          const pos = [
            (x + idx[0]) / resolution * 2 - 1,
            (y + idx[1]) / resolution * 2 - 1,
            (z + idx[2]) / resolution * 2 - 1
          ];
          vertices.push(pos);
        });
      }
    }
  }

  return vertices;
}

function createOccupancyGrid(points, resolution) {
  const grid = Array(resolution).fill(0).map(() =>
    Array(resolution).fill(0).map(() =>
      Array(resolution).fill(0)
    )
  );

  points.forEach(p => {
    const x = Math.floor((p[0] + 1) / 2 * (resolution - 1));
    const y = Math.floor((p[1] + 1) / 2 * (resolution - 1));
    const z = Math.floor((p[2] + 1) / 2 * (resolution - 1));

    if (x >= 0 && x < resolution && y >= 0 && y < resolution && z >= 0 && z < resolution) {
      grid[x][y][z] = 1;
    }
  });

  return grid;
}

function extractCube(grid, x, y, z, resolution) {
  const cube = [];
  for (let dx = 0; dx <= 1; dx++) {
    for (let dy = 0; dy <= 1; dy++) {
      for (let dz = 0; dz <= 1; dz++) {
        const val = (x + dx < resolution && y + dy < resolution && z + dz < resolution)
          ? grid[x + dx][y + dy][z + dz]
          : 0;
        cube.push(val);
      }
    }
  }
  return cube;
}

function marchCube(cube, isovalue) {
  // Simplified marching cubes
  const indices = [];
  let cubeIndex = 0;

  cube.forEach((val, i) => {
    if (val > isovalue) cubeIndex |= (1 << i);
  });

  if (cubeIndex !== 0 && cubeIndex !== 255) {
    // Add triangulated vertices (simplified)
    indices.push([0.5, 0.5, 0.5]);
  }

  return indices;
}
