/**
 * Contrastive Learning for Cross-Sensor Tactile Representation
 * Implements InfoNCE loss with temperature scaling and hard negative mining
 */

// Compute cosine similarity between two vectors
export function cosineSimilarity(a, b) {
  const dotProduct = a.reduce((sum, val, i) => sum + val * b[i], 0);
  const magA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
  const magB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
  return dotProduct / (magA * magB + 1e-8);
}

// InfoNCE loss for contrastive learning
export function infoNCELoss(anchor, positive, negatives, temperature = 0.07) {
  const simPos = cosineSimilarity(anchor, positive) / temperature;
  const simNegs = negatives.map(neg => cosineSimilarity(anchor, neg) / temperature);

  const expPos = Math.exp(simPos);
  const expNegsSum = simNegs.reduce((sum, sim) => sum + Math.exp(sim), 0);

  const loss = -Math.log(expPos / (expPos + expNegsSum + 1e-8));
  return loss;
}

// Triplet loss with margin
export function tripletLoss(anchor, positive, negative, margin = 0.2) {
  const distPos = euclideanDistance(anchor, positive);
  const distNeg = euclideanDistance(anchor, negative);
  return Math.max(0, distPos - distNeg + margin);
}

function euclideanDistance(a, b) {
  return Math.sqrt(a.reduce((sum, val, i) => sum + (val - b[i]) ** 2, 0));
}

// Simple feedforward network for encoding tactile data
export class TactileEncoder {
  constructor(inputDim, embeddingDim, hiddenDims = [128, 64]) {
    this.inputDim = inputDim;
    this.embeddingDim = embeddingDim;
    this.hiddenDims = hiddenDims;

    // Initialize random weights (in real impl, these would be trained)
    this.weights = this.initializeWeights();
  }

  initializeWeights() {
    const dims = [this.inputDim, ...this.hiddenDims, this.embeddingDim];
    const weights = [];

    for (let i = 0; i < dims.length - 1; i++) {
      const W = Array(dims[i + 1]).fill(0).map(() =>
        Array(dims[i]).fill(0).map(() => (Math.random() - 0.5) * 0.2)
      );
      const b = Array(dims[i + 1]).fill(0).map(() => (Math.random() - 0.5) * 0.1);
      weights.push({ W, b });
    }

    return weights;
  }

  forward(input) {
    let activation = input;

    for (let i = 0; i < this.weights.length; i++) {
      const { W, b } = this.weights[i];
      activation = this.linearLayer(activation, W, b);

      // ReLU activation (except last layer)
      if (i < this.weights.length - 1) {
        activation = activation.map(x => Math.max(0, x));
      }
    }

    // L2 normalize the embedding
    return this.l2Normalize(activation);
  }

  linearLayer(input, W, b) {
    return W.map((weights, i) => {
      const sum = weights.reduce((acc, w, j) => acc + w * input[j], 0);
      return sum + b[i];
    });
  }

  l2Normalize(vec) {
    const norm = Math.sqrt(vec.reduce((sum, x) => sum + x * x, 0));
    return vec.map(x => x / (norm + 1e-8));
  }

  updateWeights(learningRate = 0.001) {
    // Simulate weight updates (simplified SGD)
    this.weights.forEach(layer => {
      layer.W = layer.W.map(row =>
        row.map(w => w + (Math.random() - 0.5) * learningRate)
      );
      layer.b = layer.b.map(b => b + (Math.random() - 0.5) * learningRate);
    });
  }
}

// Hard negative mining: select negatives that are close to anchor but wrong class
export function mineHardNegatives(anchor, negatives, k = 5) {
  const similarities = negatives.map((neg, idx) => ({
    idx,
    sim: cosineSimilarity(anchor, neg)
  }));

  // Sort by similarity (descending) and take top k
  similarities.sort((a, b) => b.sim - a.sim);
  return similarities.slice(0, k).map(s => negatives[s.idx]);
}

// Compute embedding alignment score across sensors
export function computeAlignmentScore(embeddings1, embeddings2) {
  if (embeddings1.length !== embeddings2.length) {
    return 0;
  }

  const similarities = embeddings1.map((emb1, i) =>
    cosineSimilarity(emb1, embeddings2[i])
  );

  return similarities.reduce((a, b) => a + b, 0) / similarities.length;
}

// t-SNE dimensionality reduction (simplified 2D projection)
export function tsneProjection(embeddings, perplexity = 30, iterations = 1000) {
  const n = embeddings.length;

  // Initialize random 2D positions
  let positions = Array(n).fill(0).map(() => [
    Math.random() * 2 - 1,
    Math.random() * 2 - 1
  ]);

  const learningRate = 100;
  const momentum = 0.5;
  let velocities = Array(n).fill(0).map(() => [0, 0]);

  // Compute pairwise affinities in high-dimensional space
  const affinities = computeAffinities(embeddings, perplexity);

  // Gradient descent
  for (let iter = 0; iter < iterations; iter++) {
    const lr = learningRate / (1 + iter / 100);

    for (let i = 0; i < n; i++) {
      const grad = [0, 0];

      for (let j = 0; j < n; j++) {
        if (i === j) continue;

        const diff = [
          positions[i][0] - positions[j][0],
          positions[i][1] - positions[j][1]
        ];
        const dist = Math.sqrt(diff[0] * diff[0] + diff[1] * diff[1]) + 1e-8;
        const qij = 1 / (1 + dist * dist);

        const force = 4 * (affinities[i][j] - qij) * qij / dist;
        grad[0] += force * diff[0];
        grad[1] += force * diff[1];
      }

      velocities[i][0] = momentum * velocities[i][0] - lr * grad[0];
      velocities[i][1] = momentum * velocities[i][1] - lr * grad[1];

      positions[i][0] += velocities[i][0];
      positions[i][1] += velocities[i][1];
    }
  }

  return positions;
}

function computeAffinities(embeddings, perplexity) {
  const n = embeddings.length;
  const affinities = Array(n).fill(0).map(() => Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    const distances = embeddings.map((emb, j) =>
      i === j ? Infinity : euclideanDistance(embeddings[i], emb)
    );

    const sigma = Math.sqrt(perplexity);

    for (let j = 0; j < n; j++) {
      if (i !== j) {
        affinities[i][j] = Math.exp(-distances[j] * distances[j] / (2 * sigma * sigma));
      }
    }

    // Normalize
    const sum = affinities[i].reduce((a, b) => a + b, 0);
    affinities[i] = affinities[i].map(a => a / (sum + 1e-8));
  }

  return affinities;
}
